L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "\227\129\132\227\130\132\227\128\129\227\129\170\227\129\139\227\129\170\227\129\139\227\130\132\227\130\139\227\129\152\227\130\131\227\129\173\227\129\135\227\129\139\239\188\129\227\128\128\227\129\190\227\130\139\227\129\167\227\130\179\227\131\162\227\131\137\227\131\137\227\131\169\227\130\180\227\131\179\227\129\174\227\130\136\227\129\134\227\129\160\227\129\163\227\129\159\227\129\158\239\188\129\227\128\128\227\129\147\227\129\174\227\131\136\227\131\159\227\131\188\230\167\152\227\129\140\232\170\141\227\130\129\227\129\166\227\130\132\227\130\139\239\188\129"
