L9_1 = "\229\147\135\239\188\140\229\190\136\229\188\183\230\172\184\239\188\129\229\165\189\229\131\143\228\184\128\233\154\187\231\167\145\232\142\171\229\164\154\233\190\141\239\188\129\230\185\175\231\177\179\230\136\145\232\170\141\229\144\140\228\189\160\231\154\132\232\136\158\230\138\128\239\188\129"
L8_1.m_Talk_TWN = L9_1
L9_1 = "\224\185\128\224\184\173\224\185\137\224\184\162 \224\185\132\224\184\161\224\185\136\224\185\128\224\184\165\224\184\167\224\185\128\224\184\165\224\184\162\224\184\153\224\184\176\224\185\128\224\184\153\224\184\181\224\185\136\224\184\162! \224\184\173\224\184\162\224\185\136\224\184\178\224\184\135\224\184\129\224\184\177\224\184\154\224\184\148\224\184\185\224\184\161\224\184\177\224\184\135\224\184\129\224\184\163\224\185\130\224\184\132\224\185\130\224\184\161\224\185\130\224\184\148\224\185\131\224\184\153\224\184\155\224\185\136\224\184\178\224\185\128\224\184\165\224\184\162! \224\184\151\224\184\173\224\184\161\224\184\161\224\184\181\224\185\136\224\185\131\224\184\171\224\185\137\224\184\156\224\185\136\224\184\178\224\184\153!"
